// Safely parse and validate the JSON response returned by Claude
const item = $input.first().json;
const candidateName = $('Prepare LLM Payload').first().json.candidate_name;

// Handle response structure from Anthropic Messages API
let rawText = '';
if (item.content && Array.isArray(item.content) && item.content.length > 0) {
  rawText = item.content[0].text || '';
} else {
  throw new Error(`Unexpected Anthropic response structure: ${JSON.stringify(item)}`);
}

// 1. Strip markdown fences if present
let cleaned = rawText.trim();
const fenceMatch = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fenceMatch) {
  cleaned = fenceMatch[1].trim();
}

// 2. Parse JSON
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error(`Failed to parse Claude output as JSON: ${err.message}. Raw text: ${rawText}`);
}

// 3. Schema validation
const requiredKeys = ['score', 'matched_skills', 'missing_skills', 'summary', 'recommendation'];
for (const key of requiredKeys) {
  if (!(key in parsed)) {
    throw new Error(`Screening JSON output missing required key: "${key}"`);
  }
}

// Validate score bounds
const score = Number(parsed.score);
if (isNaN(score) || score < 0 || score > 100) {
  throw new Error(`Invalid score value: ${parsed.score}. Must be number between 0 and 100.`);
}

// Validate recommendation enum
const validRecs = ['shortlist', 'maybe', 'reject'];
const rec = String(parsed.recommendation).toLowerCase().trim();
if (!validRecs.includes(rec)) {
  throw new Error(`Invalid recommendation: "${parsed.recommendation}". Must be one of: ${validRecs.join(', ')}`);
}

// 4. Return flattened record ready for Google Sheets
return [{
  json: {
    timestamp: new Date().toISOString(),
    candidate_name: candidateName,
    score: Math.round(score),
    recommendation: rec,
    matched_skills: Array.isArray(parsed.matched_skills) ? parsed.matched_skills.join('; ') : String(parsed.matched_skills),
    missing_skills: Array.isArray(parsed.missing_skills) ? parsed.missing_skills.join('; ') : String(parsed.missing_skills),
    summary: String(parsed.summary || '').trim(),
    status: 'SUCCESS'
  }
}];

// Formats pipeline failure details for audit logging
const errorData = $input.first().json;

return [{
  json: {
    timestamp: new Date().toISOString(),
    failed_node: errorData.execution?.lastNodeExecuted || 'Unknown Node',
    error_message: errorData.execution?.error?.message || 'Pipeline Execution Failure',
    workflow_id: errorData.workflow?.id || 'AI-Resume-Screening-Pipeline',
    execution_id: errorData.execution?.id || null
  }
}];
